 * refetch(url, opts) - fetch with retries, exponential backoff and full jitter.
 *
 * Retries on network errors and 5xx responses; never on 4xx.
 * Backoff: base * 2^(attempt-1), with full jitter (uniform random in [0, computed]).
 * A Retry-After header (in seconds) overrides the computed backoff.
 *
 * opts:
 *   maxAttempts {number} - total attempts allowed (default 4)
 *   base        {number} - base delay in ms (default 100)
 *   onRetry     {(info: {attempt, delay, reason}) => void} - called before each retry
 *
 * Resolves with the Response on success (any non-5xx status).
 * Rejects with the last network error, or a RefetchError for exhausted retries.
 */

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

export class RefetchError extends Error {
  constructor(message, { attempts, lastResponse } = {}) {
    super(message);
    this.name = 'RefetchError';
    this.attempts = attempts;
    this.lastResponse = lastResponse;
  }
}

function computeBackoff(attempt, base) {
  const ceiling = base * Math.pow(2, attempt - 1);
  return Math.random() * ceiling; // full jitter
}

export async function refetch(url, opts = {}) {
  const {
    maxAttempts = 4,
    base = 100,
    onRetry,
    fetch: fetchImpl = fetch,
  } = opts;

  let lastError = null;
  let lastResponse = null;

  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    let response = null;
    try {
      response = await fetchImpl(url);
    } catch (err) {
      // Network error: retryable.
      lastError = err;
      if (attempt < maxAttempts) {
        const delay = computeBackoff(attempt, base);
        if (onRetry) onRetry({ attempt, delay, reason: err });
        await sleep(delay);
        continue;
      }
      throw err;
    }

    if (response.status >= 200 && response.status < 300) {
      return response;
    }

    if (response.status < 500) {
      // 4xx (and other 3xx/1xx): never retried - returned as-is.
      return response;
    }

    // 5xx: retryable.
    lastError = new Error(`Server error: ${response.status}`);
    lastResponse = response;

    if (attempt < maxAttempts) {
      let reason = lastError;
      let delay = computeBackoff(attempt, base);

      const retryAfterHeader = response.headers.get('retry-after');
      if (retryAfterHeader !== null && !Number.isNaN(Number(retryAfterHeader))) {
        const seconds = Number(retryAfterHeader);
        if (seconds >= 0) {
          delay = seconds * 1000; // Retry-After overrides computed backoff
          reason = new Error(`Server error: ${response.status} (Retry-After: ${seconds}s)`);
        }
      }

      if (onRetry) onRetry({ attempt, delay, reason });
      await sleep(delay);
    }
  }

  throw new RefetchError(
    `refetch failed after ${maxAttempts} attempts`,
    { attempts: maxAttempts, lastResponse },
  );
}
