result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/refetch/test/server.js", "content": "import { createServer as nodeCreateServer } from 'node:http';

/**
 * Creates the test server.
 *
 * Endpoints:
 *   /flaky       - fails twice with 503, then 200 with a JSON body
 *   /always-400  - always returns 400
 *   /retry-after - once 503 with Retry-After: 1, then 200
 *
 * Returns { server, hits, start, stop } where hits is a Map of pathname -> request count.
 */
export function createTestServer() {
  const hits = new Map();
  const flakyHitsPerState = new WeakMap(); // not needed for counting; kept simple

  const server = nodeCreateServer((req, res) => {
    const path = req.url ? new URL(req.url, 'http://localhost').pathname : '/';
    hits.set(path, (hits.get(path) ?? 0) + 1);
    const n = hits.get(path);

    res.setHeader('content-type', 'application/json');

    if (path === '/flaky') {
      if (n <= 2) {
        res.statusCode = 503;
        res.end(JSON.stringify({ error: 'service unavailable', hit: n }));
      } else {
        res.statusCode = 200;
        res.end(JSON.stringify({ ok: true, message: 'recovered', hit: n }));
      }
      return;
    }

    if (path === '/always-400') {
      res.statusCode = 400;
      res.end(JSON.stringify({ error: 'bad request', hit: n }));
      return;
    }

    if (path === '/retry-after') {
      if (n === 1) {
        res.setHeader('retry-after', '1');
        res.statusCode = 503;
        res.end(JSON.stringify({ error: 'try again later', hit: n }));
      } else {
        res.statusCode = 200;
        res.end(JSON.stringify({ ok: true, message: 'back online', hit: n }));
      }
      return;
    }

    res.statusCode = 404;
    res.end(JSON.stringify({ error: 'not found' }));
  });

  function start() {
    return new Promise((resolve, reject) => {
      server.once('error', reject);
      // Port 0: OS picks an ephemeral port.
      server.listen(0, '127.0.0.1', () => {
        server.off('error', reject);
        resolve(server.address().port);
      });
    });
  }

  function stop() {
    return new Promise((resolve, reject) => {
      server.close((err) => (err && err.code !== 'ERR_SERVER_NOT_RUNNING' ? reject(err) : resolve()));
    });
  }

  return { server, hits, start, stop };
}
